window.docContents[195].resolve({"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Multi-Step-Reduction--Normal-Forms-Again":{"contents":"If t reduces to t' in zero or more steps and t' is a normal form, we\n   say that \"t' is a normal form of t.\"\n\ndef IsNormalFormOf {X : Type} (R : Relation X) (t t' : X) : Prop :=\n  Multi R t t' ∧ IsNormalForm R t'\ndef IsNormalFormOf {X : Type} (R : Relation X) (t t' : X) : Prop :=\n  Multi R t t' ∧ IsNormalForm R t'\ndef IsNormalFormOf {X : Type} (R : Relation X) (t t' : X) : Prop :=\n  Multi R t t' ∧ IsNormalForm R t'\n\n\n\n\nWhen R is deterministic (as for our language's semantics), then its normal form is unique.\n\nYOTAM: The proof can be given for the general case, i.e. that\n   determinism of a relation implies the determinism of its IsNormalFormOf\n   induced counterpart.  BCP 23: That would be a nice improvement.\n\ntheorem normal_forms_unique : Deterministic (IsNormalFormOf Step) := by\n  -- We recommend using this initial setup as-is!\n  intro x y1 y2 p1 p2\n  obtain ⟨p11, p12⟩ := p1\n  obtain ⟨p21, p22⟩ := p2\n  solution!\n    induction p11 generalizing y2 with\n    | refl a =>\n        cases p21 with\n        | refl => rfl\n        | step _ b _ h1 _ => exact absurd ⟨b, h1⟩ p12\n    | step a b c h1 h2 ih =>\n        cases p21 with\n        | refl => exact absurd ⟨b, h1⟩ p22\n        | step _ b' _ h1' h2' =>\n            have hbb : b = b' := step_deterministic _ _ _ h1 h1'\n            subst hbb\n            exact ih y2 p12 h2' p22\ntheorem normal_forms_unique : Deterministic (IsNormalFormOf Step) := by\n  -- We recommend using this initial setup as-is!\n  intro x y1 y2 p1 p2\n  obtain ⟨p11, p12⟩ := p1\n  obtain ⟨p21, p22⟩ := p2\n  sorry\ntheorem normal_forms_unique : Deterministic (IsNormalFormOf Step) := by\n  -- We recommend using this initial setup as-is!\n  intro x y1 y2 p1 p2\n  obtain ⟨p11, p12⟩ := p1\n  obtain ⟨p21, p22⟩ := p2\n  sorry\n\n\n\n\nThe Step relation is normalizing it is deterministic and always reaches a normal form\nin a finite number of steps.\n\ndef Normalizing {X : Type} (R : Relation X) : Prop :=\n  ∀ t, ∃ t', IsNormalFormOf R t t'\n\ntheorem multistep_congr_1 (t1 t1' t2 : Tm) (h : t1 ⟶* t1') : (.p t1 t2) ⟶* (.p t1' t2) := by\n  induction h with\n  | refl x => exact .refl _\n  | step x y z h1 h2 ih => exact .step _ (.p y t2) _ (.plusLeft x y t2 h1) ih\ndef Normalizing {X : Type} (R : Relation X) : Prop :=\n  ∀ t, ∃ t', IsNormalFormOf R t t'\n\ntheorem multistep_congr_1 (t1 t1' t2 : Tm) (h : t1 ⟶* t1') : (.p t1 t2) ⟶* (.p t1' t2) := by\n  induction h with\n  | refl x => exact .refl _\n  | step x y z h1 h2 ih => exact .step _ (.p y t2) _ (.plusLeft x y t2 h1) ih\ndef Normalizing {X : Type} (R : Relation X) : Prop :=\n  ∀ t, ∃ t', IsNormalFormOf R t t'\n\ntheorem multistep_congr_1 (t1 t1' t2 : Tm) (h : t1 ⟶* t1') : (.p t1 t2) ⟶* (.p t1' t2) := by\n  induction h with\n  | refl x => exact .refl _\n  | step x y z h1 h2 ih => exact .step _ (.p y t2) _ (.plusLeft x y t2 h1) ih\n\n\ntheorem multistep_congr_2 (v1 t2 t2' : Tm) (hv : IsValue v1) (h : t2 ⟶* t2') :\n    (.p v1 t2) ⟶* (.p v1 t2') := by\n  solution!\n    induction h with\n    | refl x => exact .refl _\n    | step x y z h1 h2 ih => exact .step _ (.p v1 y) _ (.plusRight v1 x y hv h1) ih\ntheorem multistep_congr_2 (v1 t2 t2' : Tm) (hv : IsValue v1) (h : t2 ⟶* t2') :\n    (.p v1 t2) ⟶* (.p v1 t2') := by\n  sorry\ntheorem multistep_congr_2 (v1 t2 t2' : Tm) (hv : IsValue v1) (h : t2 ⟶* t2') :\n    (.p v1 t2) ⟶* (.p v1 t2') := by\n  sorry\n\n\n\n\ntheorem step_normalizing : Normalizing Step := by\n  intro t\n  induction t with\n  | c n => exact ⟨.c n, .refl _, (nf_same_as_value _).mpr (.const n)⟩\n  | p t1 t2 ih1 ih2 =>\n      obtain ⟨t1', hs1, hnf1⟩ := ih1\n      obtain ⟨t2', hs2, hnf2⟩ := ih2\n      obtain ⟨n1⟩ := (nf_same_as_value _).mp hnf1\n      obtain ⟨n2⟩ := (nf_same_as_value _).mp hnf2\n      apply Exists.intro (.c (n1 + n2))\n      apply And.intro _ ((nf_same_as_value _).mpr (.const _))\n      apply multi_trans _ _ _ _ (multistep_congr_1 t1 (.c n1) t2 hs1)\n      apply multi_trans _ _ _ _ (multistep_congr_2 (.c n1) t2 (.c n2) (.const n1) hs2)\n      exact multi_single _ _ _ (.plus n1 n2)\ntheorem step_normalizing : Normalizing Step := by\n  intro t\n  induction t with\n  | c n => exact ⟨.c n, .refl _, (nf_same_as_value _).mpr (.const n)⟩\n  | p t1 t2 ih1 ih2 =>\n      obtain ⟨t1', hs1, hnf1⟩ := ih1\n      obtain ⟨t2', hs2, hnf2⟩ := ih2\n      obtain ⟨n1⟩ := (nf_same_as_value _).mp hnf1\n      obtain ⟨n2⟩ := (nf_same_as_value _).mp hnf2\n      apply Exists.intro (.c (n1 + n2))\n      apply And.intro _ ((nf_same_as_value _).mpr (.const _))\n      apply multi_trans _ _ _ _ (multistep_congr_1 t1 (.c n1) t2 hs1)\n      apply multi_trans _ _ _ _ (multistep_congr_2 (.c n1) t2 (.c n2) (.const n1) hs2)\n      exact multi_single _ _ _ (.plus n1 n2)\ntheorem step_normalizing : Normalizing Step := by\n  intro t\n  induction t with\n  | c n => exact ⟨.c n, .refl _, (nf_same_as_value _).mpr (.const n)⟩\n  | p t1 t2 ih1 ih2 =>\n      obtain ⟨t1', hs1, hnf1⟩ := ih1\n      obtain ⟨t2', hs2, hnf2⟩ := ih2\n      obtain ⟨n1⟩ := (nf_same_as_value _).mp hnf1\n      obtain ⟨n2⟩ := (nf_same_as_value _).mp hnf2\n      apply Exists.intro (.c (n1 + n2))\n      apply And.intro _ ((nf_same_as_value _).mpr (.const _))\n      apply multi_trans _ _ _ _ (multistep_congr_1 t1 (.c n1) t2 hs1)\n      apply multi_trans _ _ _ _ (multistep_congr_2 (.c n1) t2 (.c n2) (.const n1) hs2)\n      exact multi_single _ _ _ (.plus n1 n2)\n\n\n","context":"Type Systems\u0009Smallstep: Small-step Operational Semantics\u0009Multi-Step Reduction","header":"3.4.2. Normal Forms Again","id":"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Multi-Step-Reduction--Normal-Forms-Again"},"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing":{"contents":"Next we consider the typing relation of the STLC, which is\nmeant to prevent reduction from getting stuck.\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Stlc: The Simply Typed Lambda-Calculus","header":"5.4. Typing","id":"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing"}});